        expect(add(2, 3)).toBe(5);
    });

    it('adds negatives', () => {
        expect(add(-1, 1)).toBe(0);
    });

    it.each([
        [2, 3, 5],
        [0, 0, 0],
        [-1, -1, -2],
    ])('adds %i + %i = %i', (a, b, expected) => {
        expect(add(a, b)).toBe(expected);
    });
});

