import requests
import pytest

def fetch_user(api_url, user_id):
    resp = requests.get(f'{api_url}/users/{user_id}')
    resp.raise_for_status()
    return resp.json()

def test_fetch_user(monkeypatch):
    class FakeResp:
        def raise_for_status(self):
            pass
        def json(self):
            return {'id': 1, 'name': 'alice'}

    def fake_get(url):
        assert 'users/1' in url
        return FakeResp()

    monkeypatch.setattr(requests, 'get', fake_get)
    assert fetch_user('https://api.example.com', 1)['name'] == 'alice'
